package org.novasos.healthysv2.consultation;
import static org.assertj.core.api.Assertions.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test") @SpringBootTest @Import(TestcontainersConfiguration.class) @Transactional class ConsultationRepositoryIntegrationTests{
 @Autowired ConsultationRepository repository;@Autowired JdbcTemplate jdbc;
 @Test void persistsTheCompleteAggregate(){var g=graph();var c=Consultation.start(g.patient,g.professional,g.organization,null,null,"GENERAL","Check-up");c.addVitalSign(new BigDecimal("36.8"),new BigDecimal("80"),new BigDecimal("180"),120,80,65,14,new BigDecimal("99"),null,g.professional);c.addDiagnosis(g.catalog,"PRIMARY",null,null);c.addNote(g.professional,"SOAP","Normal examination");c.addObservation(g.professional,"PAIN_SCALE","0",null,null);c.addTreatment("Hydration",LocalDate.now(),LocalDate.now().plusDays(7),null);c.addFollowUp(LocalDate.now().plusDays(14),"Review",null);var saved=repository.saveAndFlush(c);var found=repository.findById(saved.getId()).orElseThrow();assertThat(found.getVitalSigns()).hasSize(1);assertThat(found.getDiagnoses()).hasSize(1);assertThat(found.getNotes()).hasSize(1);assertThat(found.getObservations()).hasSize(1);assertThat(found.getTreatments()).hasSize(1);assertThat(found.getFollowUps()).hasSize(1);assertThat(jdbc.queryForObject("select count(*) from consultation.consultation where id=?",Integer.class,saved.getId())).isOne();}
 private Graph graph(){UUID person=person(),patient=UUID.randomUUID(),proPerson=person(),professional=UUID.randomUUID(),org=UUID.randomUUID(),catalog=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,person,"PAT-"+patient);jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",professional,proPerson,"PRO-"+professional,"DOCTOR","ACTIVE");jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",org,"ORG-"+org,"Hospital");jdbc.update("insert into catalog.diagnosis_catalog(id,code,label) values (?,?,?)",catalog,"I10-"+catalog.toString().substring(0,4),"Hypertension");return new Graph(patient,professional,org,catalog);}private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,"Test","User","ACTIVE");return id;}record Graph(UUID patient,UUID professional,UUID organization,UUID catalog){}
}
